export function calculateNoteSimilarity(notes1, notes2) {
  if (!notes1 || !notes2 || notes1.length === 0 || notes2.length === 0) return 0;
  const set2 = new Set(notes2.map(n => n.toLowerCase()));
  let matches = 0;
  for (const n of notes1) {
    if (set2.has(n.toLowerCase())) matches++;
  }
  // Weighted: overlap / average of both arrays
  return matches / Math.max(notes1.length, notes2.length);
}